<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {NButton,NSelect,NConfigProvider,zhCN} from 'naive-ui'
import {api,money,type User,type Account,type Location,type Transfer} from './api/funds'
import CatalogView from './views/CatalogView.vue'
import TransfersView from './views/TransfersView.vue'
import MembersView from './views/MembersView.vue'
import UsersView from './views/UsersView.vue'
import {warehouse,type StockTransfer} from './api/warehouse'
import {membersApi,type Member} from './api/memberClaims'
import type {Sku} from './api/funds'
import SkusView from './views/SkusView.vue'
import InventoryView from './views/InventoryView.vue'
import StockTransfersView from './views/StockTransfersView.vue'
import StockTransferEditor from './components/StockTransferEditor.vue'
import TransferEditor from './components/TransferEditor.vue'
const user=ref<User|null>(null),users=ref<User[]>([]),selected=ref<string|null>(null),accounts=ref<Account[]>([]),locations=ref<Location[]>([]),transfers=ref<Transfer[]>([]),total=ref(0),tab=ref('accounts'),error=ref(''),notice=ref(''),busy=ref(false),showTransfer=ref(false),opening=ref(false)
const switching=ref(false)
const skus=ref<Sku[]>([]),stock=ref<StockTransfer[]>([]),members=ref<Member[]>([]),revision=ref(0),stockFocus=ref('')
function openStock(id:string){stockFocus.value=id;tab.value='stock'}
const focusMember=ref(''),focusClaim=ref(''),identityEpoch=ref(0)
function openMember(memberId:string,claimId:string){focusMember.value=memberId;focusClaim.value=claimId;tab.value='members'}
const trusted=computed(()=>user.value?.role==='trusted'||user.value?.role==='admin')
const roles={admin:'管理员',trusted:'受信任用户',untrusted:'普通用户'}
const nav=computed(()=>[{value:'accounts',label:'资金与记账对象'},{value:'transfers',label:'划转记录'},{value:'members',label:'成员垫付与偿还'},...(trusted.value?[{value:'approvals',label:'审批'}]:[]),{value:'stock',label:'货物转移'},{value:'inventory',label:'库存数量'},{value:'skus',label:'SKU 目录'},{value:'locations',label:'仓库与外部端点'},...(user.value?.role==='admin'?[{value:'users',label:'用户管理'}]:[])])
async function refresh(){if(!user.value)return;const epoch=identityEpoch.value,actor=user.value.id;busy.value=true;error.value='';try{const [a,l,t,s,k,w,m]=await Promise.all([api.accounts(),api.locations(),api.transfers(),api.summary(),warehouse.skus(),warehouse.transfers(),membersApi.list()]);if(epoch!==identityEpoch.value||actor!==user.value?.id)return;accounts.value=a;locations.value=l;transfers.value=t;total.value=s.total_minor;skus.value=k;stock.value=w;members.value=m;revision.value++}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function identities(){users.value=await api.users()}
async function login(){if(!selected.value||switching.value)return;switching.value=true;busy.value=true;error.value='';try{showTransfer.value=false;focusMember.value='';focusClaim.value='';identityEpoch.value++;stockFocus.value='';await api.login(selected.value);user.value=await api.me();identityEpoch.value++;tab.value='accounts';notice.value='开发账号已切换';await refresh()}catch(e){user.value=null;stock.value=[];skus.value=[];members.value=[];accounts.value=[];locations.value=[];transfers.value=[];error.value=(e as Error).message}finally{busy.value=false;switching.value=false}}
async function logout(){if(switching.value)return;switching.value=true;try{showTransfer.value=false;focusMember.value='';focusClaim.value='';identityEpoch.value++;stockFocus.value='';await api.logout();user.value=null;stock.value=[];skus.value=[];members.value=[];accounts.value=[];locations.value=[];transfers.value=[];notice.value='已退出'}catch(e){error.value=(e as Error).message}finally{switching.value=false}}
async function permissionChanged(){identityEpoch.value++;stockFocus.value='';await identities();try{user.value=await api.me();if(!nav.value.some(n=>n.value===tab.value))tab.value='accounts';await refresh()}catch(e){user.value=null;error.value=(e as Error).message}}
function create(isOpening=false){opening.value=isOpening;showTransfer.value=true}
onMounted(async()=>{try{await identities();try{user.value=await api.me();selected.value=user.value.id}catch{}await refresh()}catch(e){error.value=(e as Error).message}})
</script>
<template><NConfigProvider :locale="zhCN"><div class="shell"><header><div><h1>FGAS 资金工作台</h1><p>开发环境 / 单组织 / 人民币</p></div><div class="identity"><strong>当前开发账号：{{user?`${user.display_name}（${roles[user.role]}）`:'未登录'}}</strong><div class="login"><NSelect v-model:value="selected" placeholder="选择开发账号" :options="users.filter(u=>u.active).map(u=>({label:`${u.display_name} (${u.id})`,value:u.id}))"/><NButton :loading="busy" @click="login">切换 / 登录</NButton><NButton v-if="user" @click="logout">退出</NButton></div></div></header><p v-if="error" class="banner error" role="alert">{{error}}</p><p v-if="notice" class="banner success" role="status">{{notice}}</p><template v-if="user&&!switching"><nav><button v-for="item in nav" :key="item.value" :class="{active:tab===item.value}" @click="tab=item.value">{{item.label}}</button></nav><main><MembersView v-show="tab==='members'" :key="`${user.id}:${identityEpoch}`" :accounts="accounts" :trusted="trusted" :active="tab==='members'" :focus-member="focusMember" :focus-claim="focusClaim" @changed="refresh" @notice="notice=$event" @member="openMember"/><div v-show="tab==='stock'"><StockTransferEditor :key="`${user.id}:${identityEpoch}:editor`" :locations="locations" :skus="skus" :accounts="accounts" :funds="transfers" :members="members" :trusted="trusted" @saved="refresh"/><StockTransfersView :key="`${user.id}:${identityEpoch}:stock`" :items="stock" :locations="locations" :funds="transfers" :trusted="trusted" :focus="stockFocus" @changed="refresh"/></div><StockTransfersView v-show="tab==='approvals'" :key="`${user.id}:${identityEpoch}:approvals`" :items="stock" :locations="locations" :funds="transfers" :trusted="trusted" approvals @changed="refresh"/><template v-if="tab==='accounts'"><section class="summary"><div><span>资金账面余额</span><strong>¥ {{money(total)}}</strong><small>仅汇总标记为资金对象的真实账面余额。</small></div><div class="actions"><NButton @click="refresh" :loading="busy">刷新</NButton><NButton @click="create(true)">期初资金</NButton><NButton type="primary" @click="create()">新建划转</NButton></div></section><CatalogView mode="accounts" :accounts="accounts" :locations="locations" :editable="trusted" @changed="refresh"/></template><template v-else-if="tab==='transfers'||tab==='approvals'"><TransfersView :key="`${user.id}:${identityEpoch}`" :items="transfers" :accounts="accounts" :approvals="tab==='approvals'" :trusted="trusted" @changed="refresh" @notice="notice=$event" @member="openMember"/></template><InventoryView v-else-if="tab==='inventory'" :key="`${user.id}:${identityEpoch}:${revision}`" :locations="locations" :skus="skus" :members="members" :revision="revision" @open="openStock"/><SkusView v-else-if="tab==='skus'" :key="`${user.id}:${identityEpoch}`" :items="skus" :editable="trusted" @changed="refresh"/><CatalogView v-else-if="tab==='locations'" :key="`${user.id}:${identityEpoch}`" mode="locations" :accounts="accounts" :locations="locations" :editable="trusted" @changed="refresh"/><UsersView v-else-if="tab==='users'&&user.role==='admin'" @changed="permissionChanged"/></main><TransferEditor :key="`${user.id}:${identityEpoch}`" :show="showTransfer" :accounts="accounts" :opening="opening" @close="showTransfer=false" @saved="notice='划转'+$event;refresh()"/></template><main v-else><h2>登录开发账号开始使用</h2><p>管理员与受信任用户可过账和审批；普通用户提交的划转进入待审批。</p></main><footer>开发原型。资金与货物分别审批，库存按确认完成记录。</footer></div></NConfigProvider></template>
